/**
 * Secret names declared in rayfin.yml.
 *
 * AUTO-GENERATED — do not edit manually.
 * Regenerated by `rayfin secret set`, `rayfin secret delete`, and whenever
 * function types are generated.
 *
 * This file augments the SDK's `RayfinSecretRegistry`, which is what types
 * `ctx.Secrets` in every function. Nothing imports this file — it only needs
 * to be part of the compilation, which the functions tsconfig already
 * guarantees. Only names appear here. Values are never written to disk.
 *
 * Written to the documented shape so the project type-checks before
 * `rayfin secret set`. That command requires a deployed app, which this
 * repository cannot run during authoring. Keep the names aligned with
 * rayfin/rayfin.yml.
 */
declare module '@microsoft/fabric-user-data-functions' {
  interface RayfinSecretRegistry {
    NOTEBOOK_WORKSPACE_ID: string;
    STAGING_WORKSPACE_ID: string;
    STAGING_LAKEHOUSE_ID: string;
    ADLS_ACCOUNT: string;
    ADLS_CONTAINER: string;
    ADLS_ARCHIVE_FOLDER: string;
    ADMIN_SUBJECTS: string;
  }
}

export {};
